  ('18a62a0f-4803-4592-b5e0-bb3e09d65d4e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन के दादा और परदादा बहुत प्रसिद्ध मौलवी थे। काफिरों के देश में पैदा हुए। काफिरों के देश में मरे। परंतु वसीयत करके मरे कि लाश कर्बला ले जाई जाए। उनकी आत्मा ने इस देश में एक साँस तक न ली। उस खानदान में जो पहला हिंदुस्तानी बच्चा पैदा हुआ वह बढ़कर इफ्फन का बाप हुआ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8f5bb9ec-b878-42a2-9d0c-aa2dd98749d3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब इफ्फन के पिता सैयद मुर्तुजा हुसैन मरे तो उन्होंने यह वसीयत नहीं की कि उनकी लाश कर्बला ले जाई जाए। वह एक हिंदुस्तानी कब्रिस्तान में दफन किए गए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('073fa30b-b6b9-49ac-93a1-40851df50550', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की परदादी भी बड़ी नमाजी बीबी थीं। कर्बला, नजफ, खुरासान, काजमैन और जाने कहाँ की यात्रा कर आई थीं। परंतु जब कोई घर से जाने लगता तो वह दरवाजे पर पानी का एक घड़ा जरूर रखवातीं और माश का सदका भी जरूर उतरवातीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f93fb228-e05b-40b9-9bfc-b80145e912ee', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी भी नमाज-रोजे की पाबंद थीं परंतु जब इकलौते बेटे को चेचक निकली तो वह चारपाई के पास एक टाँग पर खड़ी हुईं और बोलीं, 'माता मोरे बच्चे को माफ करद्यो।' पूरब की रहने वाली थीं। नौ या दस बरस की थीं जब ब्याह कर लखनऊ आईं, परंतु जब तक जिंदा रहीं पूरबी बोलती रहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fb9ead44-9163-491c-8b71-46c40d9742af', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लखनऊ की उर्दू ससुराल थी। वह तो मायके की भाषा को गले लगाए रहीं क्योंकि इस भाषा के सिवा इधर-उधर कोई ऐसा नहीं था जो उनके दिल की बात समझता। जब बेटे की शादी के दिन आए तो गाने-बजाने के लिए उनका दिल फड़का परंतु मौलवी के घर गाना-बजाना भला कैसे हो सकता था! बेचारी दिल मसोसकर रह गईं। हाँ इफ्फन की छठी पर उन्होंने जी भरकर जश्न मना लिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1d18b77c-ffdc-4bfa-9ac0-abaa6337ec88', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं हिंदू-मुस्लिम भाई-भाई की बात नहीं कर रहा हूँ। मैं यह बेवकूफी क्यों करूँ! क्या मैं रोज अपने बड़े या छोटे भाई से यह कहता हूँ कि हम दोनों भाई-भाई हैं? यदि मैं नहीं कहता तो क्या आप कहते हैं? हिंदू-मुसलमान अगर भाई-भाई हैं तो कहने की जरूरत नहीं। यदि नहीं हैं तो कहने से क्या फर्क पड़ेगा। मुझे कोई चुनाव तो लड़ना नहीं है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d4364358-7081-4673-8838-d7f12255673f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं तो एक कथाकार हूँ और एक कथा सुना रहा हूँ। मैं टोपी और इफ्फन की बात कर रहा हूँ। ये इस कहानी के दो चरित्र हैं। एक का नाम बलभद्र नारायण शुक्ला है और दूसरे का नाम सैयद जरगाम मुर्तुजा। एक को टोपी कहा गया और दूसरे को इफ्फन।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
