  ('0ac76447-8f65-47fa-9415-b4c4ec2b3c2c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी भी नमाज-रोजे की पाबंद थीं परंतु जब इकलौते बेटे को चेचक निकली तो वह चारपाई के पास एक टाँग पर खड़ी हुईं और बोलीं, 'माता मोरे बच्चे को माफ करद्यो।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('24efe360-1cd9-4cdf-9761-cf91e3ce8291', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात यह थी कि इफ्फन अपने दादा के मरने के बाद पैदा हुआ था। मर्दों और औरतों के इस फर्क को ध्यान में रखना जरूरी है क्योंकि इस बात को ध्यान में रखे बगैर इफ्फन की आत्मा का नाक-नक्शा समझ में न आ सकता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d2d0eafe-ccf2-4af3-9893-2f937156bd4c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी किसी मौलवी की बेटी नहीं थीं बल्कि एक ज़मींदार की बेटी थीं। दूध-घी खाती हुई आई थीं परंतु लखनऊ आकर वह उस दही के लिए तरस गईं जो घी पिलाई हुई काली हांडियों में आसामियों के यहाँ से आया करता था। बस मायके जातीं तो लपड़-शपड़ जी भर के खा लेतीं। लखनऊ आते ही उन्हें फिर मौलविन बन जाना पड़ता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('70d5e6a4-be13-47e8-ad7b-ee33f6b9caef', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने मियां से उन्हें यही तो एक शिकायत थी कि वक्त देखें न मौका, बस मौलवी ही बने रहते हैं। ससुराल में उनकी आत्मा सदा बेचैन रही।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cd95a582-fb00-4808-a0d8-48c05062e219', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब मरने लगीं तो बेटे ने पूछा कि लाश कर्बला जाएगी या नज़फ़, तो बिगड़ गईं। बोलीं, 'ए बेटा जउन तू से हमरी लाश न संभली जाए त हमरे घर भेज दिहो।' मौत सिर पर थी इसलिए उन्हें यह याद नहीं रह गया कि अब घर कहाँ है। घरवाले कराची में हैं और घर कस्टोडियन का हो चुका है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5e7bf459-a11f-454d-9afb-7968ce0d4406', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मरते वक्त किसी को ऐसी छोटी-छोटी बातें भला कैसे याद रह सकती हैं। उस वक्त तो मनुष्य अपने सबसे ज़्यादा खूबसूरत सपने देखता है (यह कथाकार का खयाल है, क्योंकि वह अभी तक मरा नहीं है!) इफ्फन की दादी को भी अपना घर याद आया। उस घर का नाम कच्ची हवेली था। कच्ची इसलिए कि वह मिट्टी की बनी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('521d654a-62a7-443d-a680-83134b2f921b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्हें दसह्री आम का वह बीजू पेड़ याद आया जो उन्होंने अपने हाथ से लगाया था और जो उन्हीं की तरह बूढ़ा हो चुका था। ऐसी ही छोटी-छोटी और मीठी-मीठी बेशुमार चीज़ें याद आईं। वह इन चीज़ों को छोड़कर भला कर्बला या नज़फ़ कैसे जा सकती थीं!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e817e63f-dc12-4905-9f94-6f896e2a3a18', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह बनारस के 'फ़ातमैन' में दफ़न की गईं क्योंकि मुर्तुज़ा हुसैन की पोस्टिंग उन दिनों वहीं थी। इफ्फन स्कूल गया हुआ था। नौकर ने आकर खबर दी कि बीबी का देहांत हो गया। इफ्फन की दादी बीबी कही जाती थीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('7c745ead-39da-497c-bec0-a373f9e3f2ad', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन तब चौथे में पढ़ता था और टोपी से उसकी मुलाक़ात हो चुकी थी। इफ्फन को अपनी दादी से बड़ा प्यार था। प्यार तो उसे अपने अब्बू, अपनी अम्मी, अपनी बाजी और छोटी बहन नुज़हत से भी था परंतु दादी से वह ज़रा ज़्यादा प्यार किया करता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f2b6c941-3a2e-4c7e-b378-72f092409d71', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अम्मी तो कभी-कभार डाँट मार लिया करती थीं। बाजी का भी यही हाल था। अब्बू भी कभी-कभार घर को कचहरी समझकर फैसला सुनाने लगते थे। नुज़हत को जब मौका मिलता उसकी कापियों पर तस्वीरें बनाने लगती थीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a782cbb4-020a-42de-80e1-99859ec5eb89', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बस एक दादी थी जिन्होंने कभी उसका दिल नहीं दुखाया। वह रात को भी उसे बहराम डाकू, अनार परी, बारह बुर्ज़, अमीर हमज़ा, गुलबकावली, हातिमताई, पंच फुल्ला रानी की कहानियाँ सुनाया करती थीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f4b1a1b8-38bb-4e1d-a58b-1557396e587f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'सोता है संसार जागता है पाक परवरदिगार। आँखों की देखी नहीं कहती। कानों की सुनी कहती हूँ कि एक मुलुक में एक बादशाह रहा----'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f9d18126-f91b-4eeb-90dd-949f00b60c9c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 35 दादी की भाषा पर वह कभी नहीं मुस्कुराया। उसे तो अच्छी-भली लगती थी। परंतु अब्बू नहीं बोलने देते थे। और जब वह दादी से इसकी शिकायत करता तो वह हँस पड़तीं, 'अ मोरा का है बेटा! अनपढ़ गँवारन की बोली तू काहे को बोले लग्यो। तू अपने अब्बा ही की बोली बोल्यो।' बात खत्म हो जाती और कहानी शुरू हो जाती— 'त उ बादशाह का किहिस कि तुम्हारे एक ठो हिरन मार लिआव...।' यही बोली टोपी के दिल में उतर गई थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('85871075-8f4b-43fe-98e7-196d4919142a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी उसे अपनी माँ की पार्टी की दिखाई दीं। अपनी दादी से तो उसे नफरत थी, नफरत। जाने कैसी भाषा बोलती थीं। इफ्फन के अब्बू और उसकी भाषा एक थी। वह जब इफ्फन के घर जाता तो उसकी दादी ही के पास बैठने की कोशिश करता। इफ्फन की अम्मी और बाजी से वह बातचीत करने की कभी कोशिश ही न करता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('044cac58-4565-4482-a001-be105a2c388b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वे दोनों अलबत्ता20 उसकी बोली पर हँसने के लिए उसे छेड़तीं परंतु जब बात बढ़ने लगती तो दादी बीच-बचाव करवा देतीं— 'तैं काहे को जाथै उन सबन के पास मुँह पिटावे को झाड़ू मारे। चल इधिर आ...' वह डाँटकर कहतीं। परंतु हर शब्द शक्कर का खिलौना बन जाता। अमावट21 बन जाता। तिलवा22 बन जाता— और वह चुपचाप उनके पास चला जाता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9d903f3b-2abb-4ed2-bb4c-a06110b34602', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'तोरि अम्माँ का कर रहीं...' दादी हमेशा यहीं से बात शुरू करतीं। पहले तो वह चकरा जाता कि यह अम्माँ क्या होता है। फिर वह समझ गया कि माता जी को कहते हैं। यह शब्द उसे अच्छा लगा। अम्माँ। वह इस शब्द को गुड़ की डली की तरह चुभलाता रहा। अम्माँ। अब्बू। बाजी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('43c75ff6-b88f-431a-9b14-975d5a9a9e5c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर एक दिन गजब हो गया। डॉक्टर भृगु नारायण शुक्ला नीले तेल वाले के घर में भी बीसवीं सदी प्रवेश कर चुकी थी। यानी खाना मेज़-कुर्सी पर होता था। लगती तो थालियाँ ही थीं परंतु चौके पर नहीं। उस दिन ऐसा हुआ कि बैंगन का भुरता उसे ज़रा ज़्यादा अच्छा लगा। रामदुलारी खाना परोस रही थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
