  ('0ce8b25d-de24-4796-a6cb-7cec2b444f6d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 35 दादी की भाषा पर वह कभी नहीं मुस्कुराया। उसे तो अच्छी-भली लगती थी। परंतु अब्बू नहीं बोलने देते थे। और जब वह दादी से इसकी शिकायत करता तो वह हँस पड़तीं, 'अ मोरा का है बेटा! अनपढ़ गँवारन की बोली तू काहे को बोले लग्यो। तू अपने अब्बा ही की बोली बोल्यो।' बात खत्म हो जाती और कहानी शुरू हो जाती— 'त उ बादशाह का किहिस कि तुम्हारे एक ठो हिरन मार लिआव...।' यही बोली टोपी के दिल में उतर गई थी। इफ्फन की दादी उसे अपनी माँ की पार्टी की दिखाई दीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d1ff2854-caad-40fa-9e78-c03986809687', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपनी दादी से तो उसे नफरत थी, नफरत। जाने कैसी भाषा बोलती थीं। इफ्फन के अब्बू और उसकी भाषा एक थी। वह जब इफ्फन के घर जाता तो उसकी दादी ही के पास बैठने की कोशिश करता। इफ्फन की अम्मी और बाजी से वह बातचीत करने की कभी कोशिश ही न करता। वे दोनों अलबत्ता20 उसकी बोली पर हँसने के लिए उसे छेड़तीं परंतु जब बात बढ़ने लगती तो दादी बीच-बचाव करवा देतीं— 'तैं काहे को जाथै उन सबन के पास मुँह पिटावे को झाड़ू मारे। चल इधिर आ...'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7efa9f84-dcd3-480d-8287-b3bb3e360951', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु हर शब्द शक्कर का खिलौना बन जाता। अमावट21 बन जाता। तिलवा22 बन जाता— और वह चुपचाप उनके पास चला जाता। 'तोरि अम्माँ का कर रहीं...' दादी हमेशा यहीं से बात शुरू करतीं। पहले तो वह चकरा जाता कि यह अम्माँ क्या होता है। फिर वह समझ गया कि माता जी को कहते हैं। यह शब्द उसे अच्छा लगा। अम्माँ। वह इस शब्द को गुड़ की डली की तरह चुभलाता रहा। अम्माँ। अब्बू। बाजी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f925fa2a-8e00-4aa5-8b57-9b77b0552398', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर एक दिन गजब हो गया। डॉक्टर भृगु नारायण शुक्ला नीले तेल वाले के घर में भी बीसवीं सदी प्रवेश कर चुकी थी। यानी खाना मेज़-कुर्सी पर होता था। लगती तो थालियाँ ही थीं परंतु चौके पर नहीं। उस दिन ऐसा हुआ कि बैंगन का भुरता उसे ज़रा ज़्यादा अच्छा लगा। रामदुलारी खाना परोस रही थी। टोपी ने कहा— 'अम्मी, ज़रा बैंगन का भुरता।' अम्मी! मेज़ पर जितने हाथ थे रुक गए। जितनी आँखें थीं वो टोपी के चेहरे पर जम गईं। अम्मी! यह शब्द इस घर में कैसे आया। अम्मी! परंपराओं की दीवार डोलने लगी। 'ये लफ़्ज़23 तुमने कहाँ सीखा?' सुभद्रदेवी ने सवाल किया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9708aaed-bdd2-4672-81df-39e28f4f86cb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तो तुमने उसी दिन क्यों नहीं बताया?” सुभद्रादेवी ने सवाल किया। “यह झूठ है दादी!” टोपी ने कहा। उस दिन टोपी बहुत उदास रहा। वह अभी इतना बड़ा नहीं हुआ था कि झूठ और सच के किस्से में पड़ता—और सच्ची बात तो यह है कि वह इतना बड़ा कभी नहीं हो सका। उस दिन तो वह इतना पिट गया था कि उसका सारा बदन दुख रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f427482f-bfb7-4317-aaeb-fe2c6f738621', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह बस लगातार एक ही बात सोचता रहा कि अगर एक दिन के वास्ते वह मुन्नी बाबू से बड़ा हो जाता तो समझ लेता उनसे। परंतु मुन्नी बाबू से बड़ा हो जाना उसके बस में तो था नहीं। वह मुन्नी बाबू से छोटा पैदा हुआ था और उनसे छोटा ही रहा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cf9f79f2-3ce7-4383-a0c2-327e8ab7de9a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे दिन वह जब स्कूल में इफ्फन से मिला तो उसने उसे सारी बातें बता दीं। दोनों जुगराफिया का घंटा छोड़कर सरक गए। पंचम की दुकान से इफ्फन ने केले खरीदे। बात यह है कि टोपी फल के अलावा और किसी चीज़ को हाथ नहीं लगाता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('82435aa2-3fa4-40c2-9627-6fc99d93ce53', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“अइसा न हो सकत का कि हम लोग दादी बदल लें,” टोपी ने कहा। “तोरि दादी हमरे घर आ जाएँ अउर हमरि तोरे घर चली जाएँ। हमरि दादी त बोलियो तूहीं लोगन को बोल-थीन।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4de24c63-2ca2-4495-85a1-55a138458d2a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“यह नहीं हो सकता।” इफ्फन ने कहा, “अब्बूं यह बात नहीं मानेंगे। और मुझे कहानी कौन सुनाएगा? तुम्हारी दादी को बारह बुर्ज की कहानी आती है?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa46ce31-1fc2-4a07-b3fe-311aa1c0b98f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तू हम्में एक ठो दादियो न दे सकत्यो?” टोपी ने खुद अपने दिल के टूटने की आवाज़ सुनी। “जो मेरी दादी हैं वह मेरे अब्बू की अम्मा भी तो हैं।” इफ्फन ने कहा। यह बात टोपी की समझ में आ गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a3514ca1-cafa-4275-a6f7-9773001e1a1c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तुम्हारी दादी मेरी दादी की तरह बूढ़ी होंगी?” “हाँ।” “तो फिकर न करो।” इफ्फन ने कहा, “मेरी दादी कहती हैं कि बूढ़े लोग मर जाते हैं।” “हमरी दादी न मरिहें।” “मरिहे कैसे नहीं? क्या मेरी दादी झूठी हैं?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7693db55-b036-4fc3-8960-68d50b997234', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठीक उसी वक्त नौकर आया और पता चला कि इफ्फन की दादी मर गईं। इफ्फन चला गया। टोपी अकेला रह गया। वह मुँह लटकाए हुए जिमनेज़ियम में चला गया। बूढ़ा चपरासी एक तरफ बैठा बीड़ी पी रहा था। वह एक कोने में बैठकर रोने लगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0c441bf7-e54d-4e19-be4b-1a40a24cb99f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शाम को वह इफ्फन के घर गया तो वहाँ सन्नाटा था। घर भरा हुआ था। रोज़ जितने लोग हुआ करते थे उससे ज़्यादा ही लोग थे। परंतु एक दादी के न होने से टोपी के लिए घर खाली हो चुका था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('53b90f43-f648-4045-9e77-d8f8d28ea1c3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जबकि उसे दादी का नाम तक नहीं मालूम था। उसने दादी के हज़ार कहने के बाद भी उनके हाथ की कोई चीज़ नहीं खाई थी। प्रेम इन बातों का पाबंद नहीं होता। टोपी और दादी में एक ऐसा 27- भूगोल शास्त्र Reprint 2026-27$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('61f403c3-4338-44c5-a345-25ceeb668157', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 39 ही संबंध हो चुका था। इफ्फान के दादा जीवित होते तो वह भी इस संबंध को बिल्कुल उसी तरह न समझ पाते जैसे टोपी के घरवाले न समझ पाए थे। दोनों अलग-अलग अधूरे थे। एक ने दूसरे को पूरा कर दिया था। दोनों प्यासे थे। एक ने दूसरे की प्यास बुझा दी थी। दोनों अपने घरों में अजनबी और भरे घर में अकेले थे। दोनों ने एक-दूसरे का अकेलापन मिटा दिया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
