  ('17ffc0dc-cff4-45ed-88e0-40f38facc121', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'ओह यू---' बीलू ने हाथ चला दिया। टोपी लुढ़क गया। फिर वह गालियाँ बकता हुआ उठा। परंतु हेड माली बीच में आ गया और डब्बू ने अपने अलसेशियन को शुशकार31 दिया। पेट में सात सुइयाँ भुकीं तो टोपी के होश ठिकाने आए। और फिर उसने कलक्टर साहब के बँगले का रुख नहीं किया। परंतु प्रश्न यह खड़ा हो गया कि फिर आखिर वह करे क्या?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f54d5c00-aa45-4d68-94e5-cee3a37ff921', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर में ले-देकर बूढ़ी नौकरानी सीता थी जो उसका दुख-दर्द समझती थी। तो वह उसी के पल्लू में चला गया और सीता की छाया में जाने के बाद उसकी आत्मा भी छोटी हो गई। सीता को घर के सभी छोटे-बड़े डाँट लिया करते थे। टोपी को भी घर के सभी छोटे-बड़े डाँट लिया करते थे। इसलिए दोनों एक-दूसरे से प्यार करने लगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('715a9ee8-c6c7-4dde-b3fb-3a33a24dd6bd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'टेक मत किया करो बाबू!' एक रात जब मुन्नी बाबू और भैरो का दांज32 करने पर वह बहुत पिटा तो सीता ने उसे अपनी कोठरी में ले जाकर समझाना शुरू किया। बात यह हुई कि जाड़ों के दिन थे। मुन्नी बाबू के लिए कोट का नया कपड़ा आया। भैरो के लिए भी नया कोट बना। टोपी को मुन्नी बाबू का कोट मिला। कोट बिलकुल नया था। मुन्नी बाबू को पसंद नहीं आया था। फिर भी बना तो था उन्हीं के लिए। था तो उतरन।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('23a8d6a6-ae25-47b4-9ce7-35f69b04c03b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी ने वह कोट उसी वक्त दूसरी नौकरानी केतकी के बेटे को दे दिया। वह खुश हो गया। नौकरानी के बच्चे को दे दी जाने वाली चीज़ वापस तो ली नहीं जा सकती थी, इसलिए तय हुआ कि टोपी जाड़ा खाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
