  ('4d613781-8919-47eb-aa65-22b5bed4e74f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सीता ने तो बड़ी आसानी से कह दिया कि वह दसवें में पहुँच गया है, परंतु यह बात इतनी आसान नहीं थी। दसवें में पहुँचने के लिए उसे बड़े पापड़ बेलने पड़े। दो साल तो वह फेल ही हुआ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eedb6d5c-6087-4e3a-bbf1-0a23e575b633', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नवेंस में तो वह सन् उनचास ही में पहुँच गया था, परंतु दसवें में वह सन् बावन में पहुँच सका। जब वह पहली बार फेल हुआ तो मुन्नी बाबू इंटरमीडिएट में फर्स्ट आए और भैरो छठे में। सारे घर ने उसे जबान की नोक पर रख लिया। वह बहुत रोया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6aa5633c-4b55-42a1-98cb-e81d825efd82', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात यह नहीं थी कि वह गौंदी था। वह काफी तेज था परंतु उसे कोई पढ़ने ही नहीं देता था। वह जब पढ़ने बैठता मुन्नी बाबू को कोई काम निकल आता या रामदुलारी को कोई ऐसी चीज मंगवानी पड़ जाती जो नौकरों से नहीं मंगवाई जा सकती थी—यह सब कुछ न होता तो पता चलता कि भैरो ने उसकी कॉपियों के हवाई जहाज उड़ा डाले हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5bba77f5-162a-4f30-9c58-cd18bd5ea44d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे साल उसे टाइफाइड हो गया। तीसरे साल वह थर्ड डिवीजन में पास हो गया। यह थर्ड डिवीजन कलंक के टीले की तरह उसके माथे से चिपक गया। परंतु हमें उसकी मुश्किलों को भी ध्यान में रखना चाहिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e5d7dd49-e334-4702-949d-8c5ee67f57e7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सन् उनचास में वह अपने साथियों के साथ था। वह फेल हो गया। साथी आगे निकल गए। वह रह गया। सन् पचास में उसे उसी दर्जे में उन लड़कों के साथ बैठना पड़ा जो पिछले साल आठवें में थे। पीछे वालों के साथ एक ही दर्जे में बैठना कोई आसान काम नहीं है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('798a74b4-0196-4b70-8085-9760c73f7a5e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसके दोस्त दसवें में थे। वह उन्हीं से मिलता, उन्हीं के साथ खेलता। अपने साथ हो जाने वालों में से किसी के साथ उसकी दोस्ती न हो सकी। वह जब भी क्लास में बैठता उसे अपना बैठना अजीब लगता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1e6ca0a4-9915-4fcf-bcb8-6d0b6e888ce4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस पर सितम यह हुआ कि कमजोर लड़कों को मास्टर जी समझाते तो उसकी मिसाल देते—'क्या मतलब है साम अवतार (या मुहम्मद अली) बलभद्र की तरह इसी दर्जे में टिके रहना चाहते हो क्या?' यह सुनकर सारा दर्जा हँस पड़ता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b34b3bad-c8e3-44dd-b4fa-b7f0eb0476de', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हँसने वाले वे होते जो पिछले साल आठवें में थे। वह किसी-न-किसी तरह इस साल को झेल गया। परंतु जब सन् इक्यावन में भी उसे नौवें दर्जे में ही बैठना पड़ा तो वह बिल्कुल गीली मिट्टी का लौंदा हो गया, क्योंकि अब तो दसवें में भी...$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f3329045-a7c8-4db8-b1c8-dfc4512308d3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सीता ने तो बड़ी आसानी से कह दिया कि वह दसवें में पहुँच गया है, परंतु यह बात इतनी आसान नहीं थी। दसवें में पहुँचने के लिए उसे बड़े पापड़ बेलने पड़े। दो साल तो वह फेल ही हुआ। नवेंस में तो वह सन् उनचास ही में पहुँच गया था, परंतु दसवें में वह सन् बावन में पहुँच सका।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c8c78c6a-623c-422e-921e-5245ee4a82e7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह काफी तेज था परंतु उसे कोई पढ़ने ही नहीं देता था। वह जब पढ़ने बैठता मुन्नी बाबू को कोई काम निकल आता या रामदुलारी को कोई ऐसी चीज मंगवानी पड़ जाती जो नौकरों से नहीं मंगवाई जा सकती थी—यह सब कुछ न होता तो पता चलता कि भैरो ने उसकी कॉपियों के हवाई जहाज उड़ा डाले हैं। दूसरे साल उसे टाइफाइड हो गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dff939fd-1ebb-4fb8-913f-ca4a65656025', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 43 कोई उसका दोस्त नहीं रह गया था। आठवें वाले दसवें में थे। सातवें वाले उसके साथ! उनके बीच में वह अच्छा-खासा बूढ़ा दिखाई देता था। वह अपने भरे-पूरे घर ही की तरह अपने स्कूल में भी अकेला हो गया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d4a8502f-750a-48c8-b47d-86f4e6b9f241', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मास्टरों ने उसका नोटिस लेना बिलकुल ही छोड़ दिया था। कोई सवाल किया जाता और जवाब देने के लिए वह भी हाथ उठाता तो कोई मास्टर उससे जवाब न पूछता। परंतु जब उसका हाथ उठता ही रहा तो एक दिन अंग्रेजी-साहित्य के मास्टर साहब ने कहा— 'तीन बरस से यही किताब पढ़ रहे हो, तुम्हें तो सारे जवाब ज़बानी याद हो गए होंगे! इन लड़कों को अगले साल हाई स्कूल का इम्तहान देना है। तुमसे पारसाल पूछ लूँगा।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b098c91b-c5e9-4934-b318-4d317f33817c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी इतना शर्माया कि उसके काले रंग पर लाली दौड़ गई। और जब तमाम बच्चे खिलखिलाकर हँस पड़े तो वह बिलकुल मर गया। जब वह पहली बार नौवें में आया था तो वह भी इन्हीं बच्चों की तरह बिलकुल बच्चा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bfa157c7-3ddb-4f52-8647-a480d7879e9a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर उसी दिन अब्दुल वहीद ने रिसेस में वह तीर मारा कि टोपी बिलकुल बिलबिला उठा। वहीद क्लास का सबसे तेज़ लड़का था। मॉनीटर भी था। और सबसे बड़ी बात यह है कि वह लाल तेल वाले डॉक्टर शरफुद्दीन का बेटा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4e13336c-f43f-4467-b8c0-b34fde574259', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसने कहा, 'बलभद्र! अबे तो हम लोगन में का घुसता है। एठवालन से दोस्ती कर। हम लोग तो निकल जाएँगे, बाकी तुम्हें तो उन्हीं सबन के साथ रहे को हुई है।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ec331089-e071-4eea-94e1-16cafe3b82de', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह बात टोपी के दिल के आर-पार हो गई और उसने कसम खाई कि टाइफाइड हो या टाइफाइड का बाप, उसे पास होना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('843dde1e-94c1-49f3-b735-792145af7947', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु बीच में चुनाव आ गए। डॉक्टर भृगु नारायण नीले तेल वाले खड़े हो गए। अब जिस घर में कोई चुनाव के लिए खड़ा हो गया हो उसमें कोई पढ़-लिख कैसे सकता है! वह तो जब डॉक्टर साहब की ज़मानत ज़ब्त हो गई तब घर में ज़रा सन्नाटा हुआ और टोपी ने देखा कि इम्तहान सिर पर खड़ा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ab5955c0-1629-44e2-b3ef-2f5c1f09f99c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह पढ़ाई में जुट गया। परंतु ऐसे वातावरण में क्या कोई पढ़ सकता था! इसलिए उसका पास ही हो जाना बहुत था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4a397c36-c407-4dd7-8281-628011658c0f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दादी बोलीं, 'वाह! भगवान नज़र-ए-बद से बचाए। रफ़्तार अच्छी है। तीसरे बरस तीसरे दर्जे में पास तो हो गए।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('84d67bdf-1ada-4491-a807-26771ef3fde3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 43 कोई उसका दोस्त नहीं रह गया था। आठवें वाले दसवें में थे। सातवें वाले उसके साथ! उनके बीच में वह अच्छा-खासा बूढ़ा दिखाई देता था। वह अपने भरे-पूरे घर ही की तरह अपने स्कूल में भी अकेला हो गया था। मास्टरों ने उसका नोटिस लेना बिलकुल ही छोड़ दिया था। कोई सवाल किया जाता और जवाब देने के लिए वह भी हाथ उठाता तो कोई मास्टर उससे जवाब न पूछता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b471ebe7-3c4f-4137-9bc5-40cdf0b06ef8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फ़न के बारे में कुछ जान लेना इसलिए ज़रूरी है कि इफ्फ़न टोपी का पहला दोस्त था। इस इफ्फ़न को टोपी ने सदा इफ्फन कहा। इफ्फ़न ने इसका बुरा माना। परंतु वह इफ्फन पुकारने पर बोलता रहा। इसी बोलते रहने में उसकी बड़ाई थी। यह नामों का चक्कर भी अजीब होता है। उर्दू और हिंदी एक ही भाषा, हिंदवी के दो नाम हैं। परंतु आप खुद देख लीजिए कि नाम बदल जाने से कैसे-कैसे घपले हो रहे हैं। नाम कृष्ण हो तो उसे अवतार कहते हैं और मुहम्मद हो तो पैगंबर। नामों के चक्कर में पड़कर लोग यह भूल गए कि दोनों ही दूध देने वाले जानवर चराया करते थे। दोनों ही पशुपति, गोवर्धन और ब्रज-कुमार थे। इसीलिए तो कहता हूँ कि टोपी के बिना इफ्फ़न और इफ्फ़न के बिना टोपी न केवल यह कि अधूरे हैं बल्कि बेमानी हैं। इसलिए इफ्फ़न के घर चलना ज़रूरी है। यह देखना ज़रूरी है कि उसकी आत्मा के आँगन में कैसी हवाएँ चल रही हैं और परम्पराओं के पेड़ पर कैसे फल आ रहे हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('24b55787-ff86-42c4-b949-4cb2303a5c12', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फ़न की कहानी भी बहुत लंबी है। परंतु हम लोग टोपी की कहानी कह-सुन रहे हैं। इसीलिए मैं इफ्फ़न की पूरी कहानी नहीं सुनाऊँगा बल्कि केवल उतनी ही सुनाऊँगा जितनी टोपी की कहानी के लिए ज़रूरी है। मैंने इसे ज़रूरी जाना कि इफ्फ़न के बारे में आपको कुछ बता दूँ क्योंकि इफ्फ़न आपको इस कहानी में जगह-जगह दिखाई देगा। न टोपी इफ्फ़न की परछाई है और न इफ्फ़न टोपी की। ये दोनों दो आज़ाद व्यक्ति हैं। इन दोनों व्यक्तियों का डेवलपमेंट एक-दूसरे से आज़ाद तौर पर हुआ। इन दोनों को दो तरह की घरेलू परंपराएँ मिलीं। इन दोनों ने जीवन के बारे में अलग-अलग सोचा। फिर भी इफ्फ़न टोपी की कहानी का एक अटूट हिस्सा है। यह बात बहुत महत्वपूर्ण है कि इफ्फ़न टोपी की कहानी का एक अटूट हिस्सा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d4fa1ed9-b059-4da9-bec2-bfdb945cff91', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह नामों का चक्कर भी अजीब होता है। उर्दू और हिंदी एक ही भाषा, हिंदवी के दो नाम हैं। परंतु आप खुद देख लीजिए कि नाम बदल जाने से कैसे-कैसे घपले हो रहे हैं। नाम कृष्ण हो तो उसे अवतार कहते हैं और मुहम्मद हो तो पैगंबर। नामों के चक्कर में पड़कर लोग यह भूल गए कि दोनों ही दूध देने वाले जानवर चराया करते थे। दोनों ही पशुपति, गोवर्धन और ब्रज-कुमार थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
