  ('8cbe8430-5ca4-49f6-ab78-99f99afb18ff', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह नामों का चक्कर भी अजीब होता है। उर्दू और हिंदी एक ही भाषा, हिंदवी के दो नाम हैं। परंतु आप खुद देख लीजिए कि नाम बदल जाने से कैसे-कैसे घपले हो रहे हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9061c8be-3fec-4379-a1bd-a8ab200d91c0', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इन दोनों व्यक्तियों का डेवलपमेंट एक-दूसरे से आज़ाद तौर पर हुआ। इन दोनों को दो तरह की घरेलू परंपराएँ मिलीं। इन दोनों ने जीवन के बारे में अलग-अलग सोचा। फिर भी इफ्फ़न टोपी की कहानी का एक अटूट हिस्सा है। यह बात बहुत महत्वपूर्ण है कि इफ्फ़न टोपी की कहानी का एक अटूट हिस्सा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('5b52da31-8555-4a48-84b4-e48588353186', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं हिंदू-मुस्लिम भाई-भाई की बात नहीं कर रहा हूँ। मैं यह बेवकूफी क्यों करूँ! क्या मैं रोज अपने बड़े या छोटे भाई से यह कहता हूँ कि हम दोनों भाई-भाई हैं? यदि मैं नहीं कहता तो क्या आप कहते हैं? हिंदू-मुसलमान अगर भाई-भाई हैं तो कहने की जरूरत नहीं। यदि नहीं हैं तो कहने से क्या फर्क पड़ेगा। मुझे कोई चुनाव तो लड़ना नहीं है। मैं तो एक कथाकार हूँ और एक कथा सुना रहा हूँ। मैं टोपी और इफ्फन की बात कर रहा हूँ। ये इस कहानी के दो चरित्र हैं। एक का नाम बलभद्र नारायण शुक्ला है और दूसरे का नाम सैयद जरगाम मुर्तुजा। एक को टोपी कहा गया और दूसरे को इफ्फन।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ad0d754a-390e-46d9-85ad-5dc9a9c3437c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन के दादा और परदादा बहुत प्रसिद्ध मौलवी थे। काफिरों के देश में पैदा हुए। काफिरों के देश में मरे। परंतु वसीयत करके मरे कि लाश कर्बला ले जाई जाए। उनकी आत्मा ने इस देश में एक साँस तक न ली। उस खानदान में जो पहला हिंदुस्तानी बच्चा पैदा हुआ वह बढ़कर इफ्फन का बाप हुआ। जब इफ्फन के पिता सैयद मुर्तुजा हुसैन मरे तो उन्होंने यह वसीयत नहीं की कि उनकी लाश कर्बला ले जाई जाए। वह एक हिंदुस्तानी कब्रिस्तान में दफन किए गए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2746ffd1-b88b-4530-a5e8-19304ed0d35a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की परदादी भी बड़ी नमाजी बीबी थीं। कर्बला, नजफ, खुरासान, काजमैन और जाने कहाँ की यात्रा कर आई थीं। परंतु जब कोई घर से जाने लगता तो वह दरवाजे पर पानी का एक घड़ा जरूर रखवातीं और माश का सदका भी जरूर उतरवातीं। इफ्फन की दादी भी नमाज-रोजे की पाबंद थीं परंतु जब इकलौते बेटे को चेचक निकली तो वह चारपाई के पास एक टाँग पर खड़ी हुईं और बोलीं, 'माता मोरे बच्चे को माफ करद्यो।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b4d1fdb1-9bbd-4b24-98a1-70623296e037', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पूरब की रहने वाली थीं। नौ या दस बरस की थीं जब ब्याह कर लखनऊ आईं, परंतु जब तक जिंदा रहीं पूरबी बोलती रहीं। लखनऊ की उर्दू ससुराल थी। वह तो मायके की भाषा को गले लगाए रहीं क्योंकि इस भाषा के सिवा इधर-उधर कोई ऐसा नहीं था जो उनके दिल की बात समझता। जब बेटे की शादी के दिन आए तो गाने-बजाने के लिए उनका दिल फड़का परंतु मौलवी के घर गाना-बजाना भला कैसे हो सकता था! बेचारी दिल मसोसकर रह गईं। हाँ इफ्फन की छठी पर उन्होंने जी भरकर जश्न मना लिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e84e1939-2f3c-4d8e-9774-609b858e2a3a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात यह थी कि इफ्फन अपने दादा के मरने के बाद पैदा हुआ था। मर्दों और औरतों के इस फर्क को ध्यान में रखना जरूरी है क्योंकि इस बात को ध्यान में रखे बगैर इफ्फन की आत्मा का नाक-नक्शा समझ में न आ सकता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4e687df2-bb7d-4243-ae53-bff5d6478aa9', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं हिंदू-मुस्लिम भाई-भाई की बात नहीं कर रहा हूँ। मैं यह बेवकूफी क्यों करूँ! क्या मैं रोज अपने बड़े या छोटे भाई से यह कहता हूँ कि हम दोनों भाई-भाई हैं? यदि मैं नहीं कहता तो क्या आप कहते हैं? हिंदू-मुसलमान अगर भाई-भाई हैं तो कहने की जरूरत नहीं। यदि नहीं हैं तो कहने से क्या फर्क पड़ेगा। मुझे कोई चुनाव तो लड़ना नहीं है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cccbc236-8a3b-41a2-9430-b1de675b46a7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन के दादा और परदादा बहुत प्रसिद्ध मौलवी थे। काफिरों के देश में पैदा हुए। काफिरों के देश में मरे। परंतु वसीयत करके मरे कि लाश कर्बला ले जाई जाए। उनकी आत्मा ने इस देश में एक साँस तक न ली।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d93c3609-9c0d-46bb-8156-c84da4bb1b1f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की परदादी भी बड़ी नमाजी बीबी थीं। कर्बला, नजफ, खुरासान, काजमैन और जाने कहाँ की यात्रा कर आई थीं। परंतु जब कोई घर से जाने लगता तो वह दरवाजे पर पानी का एक घड़ा जरूर रखवातीं और माश का सदका भी जरूर उतरवातीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('928f18b6-3c14-48e7-b2ad-423bfe51345f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी भी नमाज-रोजे की पाबंद थीं परंतु जब इकलौते बेटे को चेचक निकली तो वह चारपाई के पास एक टाँग पर खड़ी हुईं और बोलीं, 'माता मोरे बच्चे को माफ करद्यो।' पूरब की रहने वाली थीं। नौ या दस बरस की थीं जब ब्याह कर लखनऊ आईं, परंतु जब तक जिंदा रहीं पूरबी बोलती रहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('81644f3e-b3b0-488a-8b13-9d612e9a7121', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लखनऊ की उर्दू ससुराल थी। वह तो मायके की भाषा को गले लगाए रहीं क्योंकि इस भाषा के सिवा इधर-उधर कोई ऐसा नहीं था जो उनके दिल की बात समझता। जब बेटे की शादी के दिन आए तो गाने-बजाने के लिए उनका दिल फड़का परंतु मौलवी के घर गाना-बजाना भला कैसे हो सकता था! बेचारी दिल मसोसकर रह गईं। हाँ इफ्फन की छठी पर उन्होंने जी भरकर जश्न मना लिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2d95992c-5856-4864-b823-0bf5e58e1bd2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी किसी मौलवी की बेटी नहीं थीं बल्कि एक ज़मींदार की बेटी थीं। दूध-घी खाती हुई आई थीं परंतु लखनऊ आकर वह उस दही के लिए तरस गईं जो घी पिलाई हुई काली हांडियों में आसामियों के यहाँ से आया करता था। बस मायके जातीं तो लपड़-शपड़ जी भर के खा लेतीं। लखनऊ आते ही उन्हें फिर मौलविन बन जाना पड़ता। अपने मियां से उन्हें यही तो एक शिकायत थी कि वक्त देखें न मौका, बस मौलवी ही बने रहते हैं। ससुराल में उनकी आत्मा सदा बेचैन रही। जब मरने लगीं तो बेटे ने पूछा कि लाश कर्बला जाएगी या नज़फ़, तो बिगड़ गईं। बोलीं, 'ए बेटा जउन तू से हमरी लाश न संभली जाए त हमरे घर भेज दिहो।' मौत सिर पर थी इसलिए उन्हें यह याद नहीं रह गया कि अब घर कहाँ है। घरवाले कराची में हैं और घर कस्टोडियन का हो चुका है। मरते वक्त किसी को ऐसी छोटी-छोटी बातें भला कैसे याद रह सकती हैं। उस वक्त तो मनुष्य अपने सबसे ज़्यादा खूबसूरत सपने देखता है (यह कथाकार का खयाल है, क्योंकि वह अभी तक मरा नहीं है!) इफ्फन की दादी को भी अपना घर याद आया। उस घर का नाम कच्ची हवेली था। कच्ची इसलिए कि वह मिट्टी की बनी थी। उन्हें दसह्री आम का वह बीजू पेड़ याद आया जो उन्होंने अपने हाथ से लगाया था और जो उन्हीं की तरह बूढ़ा हो चुका था। ऐसी ही छोटी-छोटी और मीठी-मीठी बेशुमार चीज़ें याद आईं। वह इन चीज़ों को छोड़कर भला कर्बला या नज़फ़ कैसे जा सकती थीं! वह बनारस के 'फ़ातमैन' में दफ़न की गईं क्योंकि मुर्तुज़ा हुसैन की पोस्टिंग उन दिनों वहीं थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1e98e12e-865f-4800-acd6-dcb6ebf8a245', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन स्कूल गया हुआ था। नौकर ने आकर खबर दी कि बीबी का देहांत हो गया। इफ्फन की दादी बीबी कही जाती थीं। इफ्फन तब चौथे में पढ़ता था और टोपी से उसकी मुलाक़ात हो चुकी थी। इफ्फन को अपनी दादी से बड़ा प्यार था। प्यार तो उसे अपने अब्बू, अपनी अम्मी, अपनी बाजी और छोटी बहन नुज़हत से भी था परंतु दादी से वह ज़रा ज़्यादा प्यार किया करता था। अम्मी तो कभी-कभार डाँट मार लिया करती थीं। बाजी का भी यही हाल था। अब्बू भी कभी-कभार घर को कचहरी समझकर फैसला सुनाने लगते थे। नुज़हत को जब मौका मिलता उसकी कापियों पर तस्वीरें बनाने लगती थीं। बस एक दादी थी जिन्होंने कभी उसका दिल नहीं दुखाया। वह रात को भी उसे बहराम डाकू, अनार परी, बारह बुर्ज़, अमीर हमज़ा, गुलबकावली, हातिमताई, पंच फुल्ला रानी की कहानियाँ सुनाया करती थीं। 'सोता है संसार जागता है पाक परवरदिगार। आँखों की देखी नहीं कहती। कानों की सुनी कहती हूँ कि एक मुलुक में एक बादशाह रहा----'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7275c333-59ec-40ae-8cf6-a2726a4decf8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी किसी मौलवी की बेटी नहीं थीं बल्कि एक ज़मींदार की बेटी थीं। दूध-घी खाती हुई आई थीं परंतु लखनऊ आकर वह उस दही के लिए तरस गईं जो घी पिलाई हुई काली हांडियों में आसामियों के यहाँ से आया करता था। बस मायके जातीं तो लपड़-शपड़ जी भर के खा लेतीं। लखनऊ आते ही उन्हें फिर मौलविन बन जाना पड़ता। अपने मियां से उन्हें यही तो एक शिकायत थी कि वक्त देखें न मौका, बस मौलवी ही बने रहते हैं। ससुराल में उनकी आत्मा सदा बेचैन रही।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
