  ('429ac6d4-15d8-48ad-930e-8b9eafee33f4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन की दादी किसी मौलवी की बेटी नहीं थीं बल्कि एक ज़मींदार की बेटी थीं। दूध-घी खाती हुई आई थीं परंतु लखनऊ आकर वह उस दही के लिए तरस गईं जो घी पिलाई हुई काली हांडियों में आसामियों के यहाँ से आया करता था। बस मायके जातीं तो लपड़-शपड़ जी भर के खा लेतीं। लखनऊ आते ही उन्हें फिर मौलविन बन जाना पड़ता। अपने मियां से उन्हें यही तो एक शिकायत थी कि वक्त देखें न मौका, बस मौलवी ही बने रहते हैं। ससुराल में उनकी आत्मा सदा बेचैन रही।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4654c95c-b23a-4721-be3f-5796f661cd7f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मरते वक्त किसी को ऐसी छोटी-छोटी बातें भला कैसे याद रह सकती हैं। उस वक्त तो मनुष्य अपने सबसे ज़्यादा खूबसूरत सपने देखता है (यह कथाकार का खयाल है, क्योंकि वह अभी तक मरा नहीं है!) इफ्फन की दादी को भी अपना घर याद आया। उस घर का नाम कच्ची हवेली था। कच्ची इसलिए कि वह मिट्टी की बनी थी। उन्हें दसह्री आम का वह बीजू पेड़ याद आया जो उन्होंने अपने हाथ से लगाया था और जो उन्हीं की तरह बूढ़ा हो चुका था। ऐसी ही छोटी-छोटी और मीठी-मीठी बेशुमार चीज़ें याद आईं। वह इन चीज़ों को छोड़कर भला कर्बला या नज़फ़ कैसे जा सकती थीं!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('58eff9ee-427a-49cd-9076-97494dcd6afb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फन को अपनी दादी से बड़ा प्यार था। प्यार तो उसे अपने अब्बू, अपनी अम्मी, अपनी बाजी और छोटी बहन नुज़हत से भी था परंतु दादी से वह ज़रा ज़्यादा प्यार किया करता था। अम्मी तो कभी-कभार डाँट मार लिया करती थीं। बाजी का भी यही हाल था। अब्बू भी कभी-कभार घर को कचहरी समझकर फैसला सुनाने लगते थे। नुज़हत को जब मौका मिलता उसकी कापियों पर तस्वीरें बनाने लगती थीं। बस एक दादी थी जिन्होंने कभी उसका दिल नहीं दुखाया। वह रात को भी उसे बहराम डाकू, अनार परी, बारह बुर्ज़, अमीर हमज़ा, गुलबकावली, हातिमताई, पंच फुल्ला रानी की कहानियाँ सुनाया करती थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3cc8a90f-9bae-40a4-81b3-6f64c46f9550', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 35 दादी की भाषा पर वह कभी नहीं मुस्कुराया। उसे तो अच्छी-भली लगती थी। परंतु अब्बू नहीं बोलने देते थे। और जब वह दादी से इसकी शिकायत करता तो वह हँस पड़तीं, 'अ मोरा का है बेटा! अनपढ़ गँवारन की बोली तू काहे को बोले लग्यो। तू अपने अब्बा ही की बोली बोल्यो।' बात खत्म हो जाती और कहानी शुरू हो जाती— 'त उ बादशाह का किहिस कि तुम्हारे एक ठो हिरन मार लिआव...।' यही बोली टोपी के दिल में उतर गई थी। इफ्फन की दादी उसे अपनी माँ की पार्टी की दिखाई दीं। अपनी दादी से तो उसे नफरत थी, नफरत। जाने कैसी भाषा बोलती थीं। इफ्फन के अब्बू और उसकी भाषा एक थी। वह जब इफ्फन के घर जाता तो उसकी दादी ही के पास बैठने की कोशिश करता। इफ्फन की अम्मी और बाजी से वह बातचीत करने की कभी कोशिश ही न करता। वे दोनों अलबत्ता20 उसकी बोली पर हँसने के लिए उसे छेड़तीं परंतु जब बात बढ़ने लगती तो दादी बीच-बचाव करवा देतीं— 'तैं काहे को जाथै उन सबन के पास मुँह पिटावे को झाड़ू मारे। चल इधिर आ...' वह डाँटकर कहतीं। परंतु हर शब्द शक्कर का खिलौना बन जाता। अमावट21 बन जाता। तिलवा22 बन जाता— और वह चुपचाप उनके पास चला जाता। 'तोरि अम्माँ का कर रहीं...' दादी हमेशा यहीं से बात शुरू करतीं। पहले तो वह चकरा जाता कि यह अम्माँ क्या होता है। फिर वह समझ गया कि माता जी को कहते हैं। यह शब्द उसे अच्छा लगा। अम्माँ। वह इस शब्द को गुड़ की डली की तरह चुभलाता रहा। अम्माँ। अब्बू। बाजी। फिर एक दिन गजब हो गया। डॉक्टर भृगु नारायण शुक्ला नीले तेल वाले के घर में भी बीसवीं सदी प्रवेश कर चुकी थी। यानी खाना मेज़-कुर्सी पर होता था। लगती तो थालियाँ ही थीं परंतु चौके पर नहीं। उस दिन ऐसा हुआ कि बैंगन का भुरता उसे ज़रा ज़्यादा अच्छा लगा। रामदुलारी खाना परोस रही थी। टोपी ने कहा— 'अम्मी, ज़रा बैंगन का भुरता।' अम्मी! मेज़ पर जितने हाथ थे रुक गए। जितनी आँखें थीं वो टोपी के चेहरे पर जम गईं। अम्मी! यह शब्द इस घर में कैसे आया। अम्मी! परंपराओं की दीवार डोलने लगी। 'ये लफ़्ज़23 तुमने कहाँ सीखा?' सुभद्रदेवी ने सवाल किया। 20- बल्कि 21- पके आम के रस को सुखाकर बनाई गई मोटी परत 22- तिल का लड्डू/तिल से बने व्यंजन 23- शब्द Reprint 2026-27$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0f9f5db4-5af7-4670-9e57-d0a44d5f6d46', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 35 दादी की भाषा पर वह कभी नहीं मुस्कुराया। उसे तो अच्छी-भली लगती थी। परंतु अब्बू नहीं बोलने देते थे। और जब वह दादी से इसकी शिकायत करता तो वह हँस पड़तीं, 'अ मोरा का है बेटा! अनपढ़ गँवारन की बोली तू काहे को बोले लग्यो। तू अपने अब्बा ही की बोली बोल्यो।' बात खत्म हो जाती और कहानी शुरू हो जाती— 'त उ बादशाह का किहिस कि तुम्हारे एक ठो हिरन मार लिआव...।' यही बोली टोपी के दिल में उतर गई थी। इफ्फन की दादी उसे अपनी माँ की पार्टी की दिखाई दीं। अपनी दादी से तो उसे नफरत थी, नफरत। जाने कैसी भाषा बोलती थीं। इफ्फन के अब्बू और उसकी भाषा एक थी। वह जब इफ्फन के घर जाता तो उसकी दादी ही के पास बैठने की कोशिश करता। इफ्फन की अम्मी और बाजी से वह बातचीत करने की कभी कोशिश ही न करता। वे दोनों अलबत्ता20 उसकी बोली पर हँसने के लिए उसे छेड़तीं परंतु जब बात बढ़ने लगती तो दादी बीच-बचाव करवा देतीं— 'तैं काहे को जाथै उन सबन के पास मुँह पिटावे को झाड़ू मारे। चल इधिर आ...' वह डाँटकर कहतीं। परंतु हर शब्द शक्कर का खिलौना बन जाता। अमावट21 बन जाता। तिलवा22 बन जाता— और वह चुपचाप उनके पास चला जाता। 'तोरि अम्माँ का कर रहीं...' दादी हमेशा यहीं से बात शुरू करतीं। पहले तो वह चकरा जाता कि यह अम्माँ क्या होता है। फिर वह समझ गया कि माता जी को कहते हैं। यह शब्द उसे अच्छा लगा। अम्माँ। वह इस शब्द को गुड़ की डली की तरह चुभलाता रहा। अम्माँ। अब्बू। बाजी। फिर एक दिन गजब हो गया। डॉक्टर भृगु नारायण शुक्ला नीले तेल वाले के घर में भी बीसवीं सदी प्रवेश कर चुकी थी। यानी खाना मेज़-कुर्सी पर होता था। लगती तो थालियाँ ही थीं परंतु चौके पर नहीं। उस दिन ऐसा हुआ कि बैंगन का भुरता उसे ज़रा ज़्यादा अच्छा लगा। रामदुलारी खाना परोस रही थी। टोपी ने कहा— 'अम्मी, ज़रा बैंगन का भुरता।' अम्मी! मेज़ पर जितने हाथ थे रुक गए। जितनी आँखें थीं वो टोपी के चेहरे पर जम गईं। अम्मी! यह शब्द इस घर में कैसे आया। अम्मी! परंपराओं की दीवार डोलने लगी। 'ये लफ़्ज़23 तुमने कहाँ सीखा?' सुभद्रदेवी ने सवाल किया। 20- बल्कि 21- पके आम के रस को सुखाकर बनाई गई मोटी परत 22- तिल का लड्डू/तिल से बने व्यंजन 23- शब्द Reprint 2026-27$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
