  ('39cbd126-3341-4e39-9218-2c5a5ad1098c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तो तुमने उसी दिन क्यों नहीं बताया?” सुभद्रादेवी ने सवाल किया। “यह झूठ है दादी!” टोपी ने कहा। उस दिन टोपी बहुत उदास रहा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('057576fa-99a2-49e9-9cd7-3b4256ddcb4e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह अभी इतना बड़ा नहीं हुआ था कि झूठ और सच के किस्से में पड़ता—और सच्ची बात तो यह है कि वह इतना बड़ा कभी नहीं हो सका। उस दिन तो वह इतना पिट गया था कि उसका सारा बदन दुख रहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1dadc461-c2c7-4e9a-8a5f-323562ea5952', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह बस लगातार एक ही बात सोचता रहा कि अगर एक दिन के वास्ते वह मुन्नी बाबू से बड़ा हो जाता तो समझ लेता उनसे। परंतु मुन्नी बाबू से बड़ा हो जाना उसके बस में तो था नहीं। वह मुन्नी बाबू से छोटा पैदा हुआ था और उनसे छोटा ही रहा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9e95bbbd-9116-4fa3-9721-fcfb35de1e6f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे दिन वह जब स्कूल में इफ्फन से मिला तो उसने उसे सारी बातें बता दीं। दोनों जुगराफिया का घंटा छोड़कर सरक गए। पंचम की दुकान से इफ्फन ने केले खरीदे। बात यह है कि टोपी फल के अलावा और किसी चीज़ को हाथ नहीं लगाता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('31a29fff-70e6-44a5-8389-45645c6fbb2d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“अइसा न हो सकत का कि हम लोग दादी बदल लें,” टोपी ने कहा। “तोरि दादी हमरे घर आ जाएँ अउर हमरि तोरे घर चली जाएँ। हमरि दादी त बोलियो तूहीं लोगन को बोल-थीन।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cad3cebb-f84b-4e7b-953b-caa89eb225af', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“यह नहीं हो सकता।” इफ्फन ने कहा, “अब्बूं यह बात नहीं मानेंगे। और मुझे कहानी कौन सुनाएगा? तुम्हारी दादी को बारह बुर्ज की कहानी आती है?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('803fb111-0826-40bc-a1e8-aaefcd065304', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तू हम्में एक ठो दादियो न दे सकत्यो?” टोपी ने खुद अपने दिल के टूटने की आवाज़ सुनी। “जो मेरी दादी हैं वह मेरे अब्बू की अम्मा भी तो हैं।” इफ्फन ने कहा। यह बात टोपी की समझ में आ गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5fad1ba6-c23e-40a5-8f7a-0d29dd53a536', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“तुम्हारी दादी मेरी दादी की तरह बूढ़ी होंगी?” “हाँ।” “तो फिकर न करो।” इफ्फन ने कहा, “मेरी दादी कहती हैं कि बूढ़े लोग मर जाते हैं।” “हमरी दादी न मरिहें।” “मरिहे कैसे नहीं? क्या मेरी दादी झूठी हैं?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e7dff3ab-ad0d-4b6e-8257-0c517091c7fe', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठीक उसी वक्त नौकर आया और पता चला कि इफ्फन की दादी मर गईं। इफ्फन चला गया। टोपी अकेला रह गया। वह मुँह लटकाए हुए जिमनेज़ियम में चला गया। बूढ़ा चपरासी एक तरफ बैठा बीड़ी पी रहा था। वह एक कोने में बैठकर रोने लगा। शाम को वह इफ्फन के घर गया तो वहाँ सन्नाटा था। घर भरा हुआ था। रोज़ जितने लोग हुआ करते थे उससे ज़्यादा ही लोग थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b4be141a-1741-48ea-b9d9-fa04a1b9159b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु एक दादी के न होने से टोपी के लिए घर खाली हो चुका था। जबकि उसे दादी का नाम तक नहीं मालूम था। उसने दादी के हज़ार कहने के बाद भी उनके हाथ की कोई चीज़ नहीं खाई थी। प्रेम इन बातों का पाबंद नहीं होता। टोपी और दादी में एक ऐसा 27- भूगोल शास्त्र Reprint 2026-27$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0b1cfe91-6ab9-4785-841d-456ca3323a86', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 39 ही संबंध हो चुका था। इफ्फान के दादा जीवित होते तो वह भी इस संबंध को बिल्कुल उसी तरह न समझ पाते जैसे टोपी के घरवाले न समझ पाए थे। दोनों अलग-अलग अधूरे थे। एक ने दूसरे को पूरा कर दिया था। दोनों प्यासे थे। एक ने दूसरे की प्यास बुझा दी थी। दोनों अपने घरों में अजनबी और भरे घर में अकेले थे। दोनों ने एक-दूसरे का अकेलापन मिटा दिया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4a62e17d-87a4-40da-8854-0b1bcf956342', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बहत्तर बरस की थी और दूसरा आठ साल का। 'तोरी दादी की जगह हमरी दादी मर गई होती तो ठीक भया होता।' टोपी ने इफ्फान को पुरसा दिया। इफ्फान ने कोई जवाब नहीं दिया। उसे इस बात का जवाब आता ही नहीं था। दोनों दोस्त चुपचाप रोने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('567ec12e-31a3-4b10-8e76-7c24145098fb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी ने दस अक्टूबर सन पैंतालीस को कसम खाई कि अब वह किसी ऐसे लड़के से दोस्ती नहीं करेगा जिसका बाप ऐसी नौकरी करता हो जिसमें बदली होती रहती है। दस अक्टूबर सन पैंतालीस का यूँ तो कोई महत्व नहीं परंतु टोपी के आत्म-इतिहास में इस तारीख का बहुत महत्व है, क्योंकि इसी तारीख को इफ्फान के पिता बदली पर मुरादाबाद चले गए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9a46ab93-7dd9-497f-b1d0-147db48a9f8e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इफ्फान की दादी के मरने के थोड़े ही दिनों बाद यह तबादला हुआ था, इसलिए टोपी और अकेला हो गया क्योंकि दूसरे कलेक्टर ठाकुर हरिनाम सिंह के तीन लड़कों में से कोई उसका दोस्त न बन सका।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e458066f-3d1d-4d64-b115-577f73164678', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$डब्बू बहुत छोटा था। बिल्लू बहुत बड़ा था। गुंगु था तो बराबर का परंतु केवल अंग्रेजी बोलता था। और यह बात भी थी कि उन तीनों को इसका एहसास था कि वे कलेक्टर के बेटे हैं। किसी ने टोपी को मुँह नहीं लगाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('821eec4f-a200-41be-9034-635f40e2bc62', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$माली और चपरासी टोपी को पहचानते थे। इसलिए वह बंगले में चला गया। बिल्लू, गुंगु और डब्बू उस समय क्रिकेट खेल रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('33f557c7-2c51-4c88-a4bc-483c1af0b81c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$डब्बू ने हिट किया। गेंद सीधी टोपी के मुँह पर आई। उसने घबराकर हाथ उठाया। गेंद उसके हाथों में आ गई। 'हाउज़ दैट!' हेड माली अंपायर था। उसने उँगली उठा दी। वह बेचारा केवल यह समझ सका कि जब 'हाउज़ दैट' का शोर हो तो उसे उँगली उठा देनी चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('25d599f3-2aff-4123-947e-f36083c8e14a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'हू आर यू?' डब्बू ने सवाल किया। 'बलभद्र नारायण।' टोपी ने जवाब दिया। 'हू इज़ योर फादर?' यह सवाल गुंगु ने किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f1cc76d1-65d7-43e1-b7b4-0135d0db08c8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों अलग-अलग अधूरे थे। एक ने दूसरे को पूरा कर दिया था। दोनों प्यासे थे। एक ने दूसरे की प्यास बुझा दी थी। दोनों अपने घरों में अजनबी और भरे घर में अकेले थे। दोनों ने एक-दूसरे का अकेलापन मिटा दिया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2e682bb9-f78c-448b-b17a-b7eab9aff3dd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी ने दस अक्टूबर सन पैंतालीस को कसम खाई कि अब वह किसी ऐसे लड़के से दोस्ती नहीं करेगा जिसका बाप ऐसी नौकरी करता हो जिसमें बदली होती रहती है। दस अक्टूबर सन पैंतालीस का यूँ तो कोई महत्व नहीं परंतु टोपी के आत्म-इतिहास में इस तारीख का बहुत महत्व है, क्योंकि इसी तारीख को इफ्फान के पिता बदली पर मुरादाबाद चले गए। इफ्फान की दादी के मरने के थोड़े ही दिनों बाद यह तबादला हुआ था, इसलिए टोपी और अकेला हो गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('57dc4736-bd40-4851-b0f9-ceb5c7ef204b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 41 'भृगु नारायण।' 'ऐं।' बीलू ने अंपायर को आवाज़ दी, 'ई भिरगू नारायण कौन है? ऐनी ऑफ अवर चपरासीश?' 'नाहीं साहब।' अंपायर ने कहा, 'सहर के मशहूर डागडर हैं।' 'यू मीन डॉक्टर?' डब्बू ने सवाल किया। 'यस सर!' हेड माली को इतनी अंगरेज़ी आ गई थी। 'बट ही लुक्स सो क्लमशी।' बीलू बोला। 'ए!' टोपी अकड़ गया। 'तुनी जबनिया सँभाल के बोलो। एक लप्पड़ में नाचे लखिगो।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cc68fefa-1ffc-4a4b-8188-8a914f3d19fb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'ओह यू---' बीलू ने हाथ चला दिया। टोपी लुढ़क गया। फिर वह गालियाँ बकता हुआ उठा। परंतु हेड माली बीच में आ गया और डब्बू ने अपने अलसेशियन को शुशकार31 दिया। पेट में सात सुइयाँ भुकीं तो टोपी के होश ठिकाने आए। और फिर उसने कलक्टर साहब के बँगले का रुख नहीं किया। परंतु प्रश्न यह खड़ा हो गया कि फिर आखिर वह करे क्या?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d15e9bae-f2e1-475c-a910-c71d64a7c6e4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर में ले-देकर बूढ़ी नौकरानी सीता थी जो उसका दुख-दर्द समझती थी। तो वह उसी के पल्लू में चला गया और सीता की छाया में जाने के बाद उसकी आत्मा भी छोटी हो गई। सीता को घर के सभी छोटे-बड़े डाँट लिया करते थे। टोपी को भी घर के सभी छोटे-बड़े डाँट लिया करते थे। इसलिए दोनों एक-दूसरे से प्यार करने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a04408f4-1cfe-4fa0-9ba0-fcd32583f272', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'टेक मत किया करो बाबू!' एक रात जब मुन्नी बाबू और भैरो का दांज32 करने पर वह बहुत पिटा तो सीता ने उसे अपनी कोठरी में ले जाकर समझाना शुरू किया। बात यह हुई कि जाड़ों के दिन थे। मुन्नी बाबू के लिए कोट का नया कपड़ा आया। भैरो के लिए भी नया कोट बना। टोपी को मुन्नी बाबू का कोट मिला। कोट बिलकुल नया था। मुन्नी बाबू को पसंद नहीं आया था। फिर भी बना तो था उन्हीं के लिए। था तो उतरन।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0557e490-c7f8-4563-8b28-8381192e219c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी ने वह कोट उसी वक्त दूसरी नौकरानी केतकी के बेटे को दे दिया। वह खुश हो गया। नौकरानी के बच्चे को दे दी जाने वाली चीज़ वापस तो ली नहीं जा सकती थी, इसलिए तय हुआ कि टोपी जाड़ा खाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('5333bdc4-c97e-4f31-a4b0-231968e4fa32', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'हम जाड़ा-ओड़ा न खाएँगे। भात खाएँगे।' टोपी ने कहा। 'तुम जूते खाओगे।' सुभद्रादेवी बोलीं। 'आपको इहो न मालूम कि जूता खाया न जात पहिना जात है।' 'दादी से बदतमीज़ी करते हो।' मुन्नी बाबू ने बिगड़कर कहा। 'त का हम इनकी पूजा करें।' फिर क्या था! दादी ने आसमान सिर पर उठा लिया। रामदुलारी ने उसे पीटना शुरू किया--$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('68a63dfe-00a1-43c5-a310-a71eb86df203', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 41 'भृगु नारायण।' 'ऐं।' बीलू ने अंपायर को आवाज़ दी, 'ई भिरगू नारायण कौन है? ऐनी ऑफ अवर चपरासीश?' 'नाहीं साहब।' अंपायर ने कहा, 'सहर के मशहूर डागडर हैं।' 'यू मीन डॉक्टर?' डब्बू ने सवाल किया। 'यस सर!' हेड माली को इतनी अंगरेज़ी आ गई थी। 'बट ही लुक्स सो क्लमशी।' बीलू बोला।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4e9176a2-2cfb-406a-b3b2-7af9769828aa', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी अकड़ गया। 'तुनी जबनिया सँभाल के बोलो। एक लप्पड़ में नाचे लखिगो।' 'ओह यू---' बीलू ने हाथ चला दिया। टोपी लुढ़क गया। फिर वह गालियाँ बकता हुआ उठा। परंतु हेड माली बीच में आ गया और डब्बू ने अपने अलसेशियन को शुशकार31 दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c837fe30-1c02-4e5d-abf8-b3ea170988d5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पेट में सात सुइयाँ भुकीं तो टोपी के होश ठिकाने आए। और फिर उसने कलक्टर साहब के बँगले का रुख नहीं किया। परंतु प्रश्न यह खड़ा हो गया कि फिर आखिर वह करे क्या? घर में ले-देकर बूढ़ी नौकरानी सीता थी जो उसका दुख-दर्द समझती थी। तो वह उसी के पल्लू में चला गया और सीता की छाया में जाने के बाद उसकी आत्मा भी छोटी हो गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c8cbfbf8-a1c4-49d1-b803-a42b97f39955', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी को मुन्नी बाबू का कोट मिला। कोट बिलकुल नया था। मुन्नी बाबू को पसंद नहीं आया था। फिर भी बना तो था उन्हीं के लिए। था तो उतरन। टोपी ने वह कोट उसी वक्त दूसरी नौकरानी केतकी के बेटे को दे दिया। वह खुश हो गया। नौकरानी के बच्चे को दे दी जाने वाली चीज़ वापस तो ली नहीं जा सकती थी, इसलिए तय हुआ कि टोपी जाड़ा खाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1c0e8d2c-c26a-4bde-b704-b8c32b961653', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सीता ने तो बड़ी आसानी से कह दिया कि वह दसवें में पहुँच गया है, परंतु यह बात इतनी आसान नहीं थी। दसवें में पहुँचने के लिए उसे बड़े पापड़ बेलने पड़े। दो साल तो वह फेल ही हुआ। नवेंस में तो वह सन् उनचास ही में पहुँच गया था, परंतु दसवें में वह सन् बावन में पहुँच सका। जब वह पहली बार फेल हुआ तो मुन्नी बाबू इंटरमीडिएट में फर्स्ट आए और भैरो छठे में। सारे घर ने उसे जबान की नोक पर रख लिया। वह बहुत रोया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dd5641b0-08ca-49ae-a03e-c8818b3bd6b4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात यह नहीं थी कि वह गौंदी था। वह काफी तेज था परंतु उसे कोई पढ़ने ही नहीं देता था। वह जब पढ़ने बैठता मुन्नी बाबू को कोई काम निकल आता या रामदुलारी को कोई ऐसी चीज मंगवानी पड़ जाती जो नौकरों से नहीं मंगवाई जा सकती थी—यह सब कुछ न होता तो पता चलता कि भैरो ने उसकी कॉपियों के हवाई जहाज उड़ा डाले हैं। दूसरे साल उसे टाइफाइड हो गया। तीसरे साल वह थर्ड डिवीजन में पास हो गया। यह थर्ड डिवीजन कलंक के टीले की तरह उसके माथे से चिपक गया। परंतु हमें उसकी मुश्किलों को भी ध्यान में रखना चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('067dc2aa-8974-4fe5-9db5-607e8c2d4b35', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सन् उनचास में वह अपने साथियों के साथ था। वह फेल हो गया। साथी आगे निकल गए। वह रह गया। सन् पचास में उसे उसी दर्जे में उन लड़कों के साथ बैठना पड़ा जो पिछले साल आठवें में थे। पीछे वालों के साथ एक ही दर्जे में बैठना कोई आसान काम नहीं है। उसके दोस्त दसवें में थे। वह उन्हीं से मिलता, उन्हीं के साथ खेलता। अपने साथ हो जाने वालों में से किसी के साथ उसकी दोस्ती न हो सकी। वह जब भी क्लास में बैठता उसे अपना बैठना अजीब लगता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('70787c1f-0bff-422e-b1c4-748718e7dc7c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस पर सितम यह हुआ कि कमजोर लड़कों को मास्टर जी समझाते तो उसकी मिसाल देते—'क्या मतलब है साम अवतार (या मुहम्मद अली) बलभद्र की तरह इसी दर्जे में टिके रहना चाहते हो क्या?' यह सुनकर सारा दर्जा हँस पड़ता। हँसने वाले वे होते जो पिछले साल आठवें में थे। वह किसी-न-किसी तरह इस साल को झेल गया। परंतु जब सन् इक्यावन में भी उसे नौवें दर्जे में ही बैठना पड़ा तो वह बिल्कुल गीली मिट्टी का लौंदा हो गया, क्योंकि अब तो दसवें में भी...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('109e191b-5b39-4b90-9874-1229bc5bd395', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सीता ने तो बड़ी आसानी से कह दिया कि वह दसवें में पहुँच गया है, परंतु यह बात इतनी आसान नहीं थी। दसवें में पहुँचने के लिए उसे बड़े पापड़ बेलने पड़े। दो साल तो वह फेल ही हुआ। नवेंस में तो वह सन् उनचास ही में पहुँच गया था, परंतु दसवें में वह सन् बावन में पहुँच सका। जब वह पहली बार फेल हुआ तो मुन्नी बाबू इंटरमीडिएट में फर्स्ट आए और भैरो छठे में। सारे घर ने उसे जबान की नोक पर रख लिया। वह बहुत रोया। बात यह नहीं थी कि वह गौंदी था। वह काफी तेज था परंतु उसे कोई पढ़ने ही नहीं देता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f7a30f5c-a44d-4343-9b92-583504092863', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह जब पढ़ने बैठता मुन्नी बाबू को कोई काम निकल आता या रामदुलारी को कोई ऐसी चीज मंगवानी पड़ जाती जो नौकरों से नहीं मंगवाई जा सकती थी—यह सब कुछ न होता तो पता चलता कि भैरो ने उसकी कॉपियों के हवाई जहाज उड़ा डाले हैं। दूसरे साल उसे टाइफाइड हो गया। तीसरे साल वह थर्ड डिवीजन में पास हो गया। यह थर्ड डिवीजन कलंक के टीले की तरह उसके माथे से चिपक गया। परंतु हमें उसकी मुश्किलों को भी ध्यान में रखना चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b49f8089-7710-4232-9d1d-8c70d6be704f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सन् उनचास में वह अपने साथियों के साथ था। वह फेल हो गया। साथी आगे निकल गए। वह रह गया। सन् पचास में उसे उसी दर्जे में उन लड़कों के साथ बैठना पड़ा जो पिछले साल आठवें में थे। पीछे वालों के साथ एक ही दर्जे में बैठना कोई आसान काम नहीं है। उसके दोस्त दसवें में थे। वह उन्हीं से मिलता, उन्हीं के साथ खेलता। अपने साथ हो जाने वालों में से किसी के साथ उसकी दोस्ती न हो सकी। वह जब भी क्लास में बैठता उसे अपना बैठना अजीब लगता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
