  ('36efbfb7-d7cc-4875-ab47-11eb6ebaaf56', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सीता ने तो बड़ी आसानी से कह दिया कि वह दसवें में पहुँच गया है, परंतु यह बात इतनी आसान नहीं थी। दसवें में पहुँचने के लिए उसे बड़े पापड़ बेलने पड़े। दो साल तो वह फेल ही हुआ। नवेंस में तो वह सन् उनचास ही में पहुँच गया था, परंतु दसवें में वह सन् बावन में पहुँच सका। जब वह पहली बार फेल हुआ तो मुन्नी बाबू इंटरमीडिएट में फर्स्ट आए और भैरो छठे में। सारे घर ने उसे जबान की नोक पर रख लिया। वह बहुत रोया। बात यह नहीं थी कि वह गौंदी था। वह काफी तेज था परंतु उसे कोई पढ़ने ही नहीं देता था। वह जब पढ़ने बैठता मुन्नी बाबू को कोई काम निकल आता या रामदुलारी को कोई ऐसी चीज मंगवानी पड़ जाती जो नौकरों से नहीं मंगवाई जा सकती थी—यह सब कुछ न होता तो पता चलता कि भैरो ने उसकी कॉपियों के हवाई जहाज उड़ा डाले हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0a813a1c-a6d5-4113-bcf7-3a04bdf94c13', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे साल उसे टाइफाइड हो गया। तीसरे साल वह थर्ड डिवीजन में पास हो गया। यह थर्ड डिवीजन कलंक के टीले की तरह उसके माथे से चिपक गया। परंतु हमें उसकी मुश्किलों को भी ध्यान में रखना चाहिए। सन् उनचास में वह अपने साथियों के साथ था। वह फेल हो गया। साथी आगे निकल गए। वह रह गया। सन् पचास में उसे उसी दर्जे में उन लड़कों के साथ बैठना पड़ा जो पिछले साल आठवें में थे। पीछे वालों के साथ एक ही दर्जे में बैठना कोई आसान काम नहीं है। उसके दोस्त दसवें में थे। वह उन्हीं से मिलता, उन्हीं के साथ खेलता। अपने साथ हो जाने वालों में से किसी के साथ उसकी दोस्ती न हो सकी। वह जब भी क्लास में बैठता उसे अपना बैठना अजीब लगता। उस पर सितम यह हुआ कि कमजोर लड़कों को मास्टर जी समझाते तो उसकी मिसाल देते—'क्या मतलब है साम अवतार (या मुहम्मद अली) बलभद्र की तरह इसी दर्जे में टिके रहना चाहते हो क्या?' यह सुनकर सारा दर्जा हँस पड़ता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a07b4858-385b-40dc-a163-b962f74e19c3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 43 कोई उसका दोस्त नहीं रह गया था। आठवें वाले दसवें में थे। सातवें वाले उसके साथ! उनके बीच में वह अच्छा-खासा बूढ़ा दिखाई देता था। वह अपने भरे-पूरे घर ही की तरह अपने स्कूल में भी अकेला हो गया था। मास्टरों ने उसका नोटिस लेना बिलकुल ही छोड़ दिया था। कोई सवाल किया जाता और जवाब देने के लिए वह भी हाथ उठाता तो कोई मास्टर उससे जवाब न पूछता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('785956d5-939f-4402-8745-3f225041be1b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु जब उसका हाथ उठता ही रहा तो एक दिन अंग्रेजी-साहित्य के मास्टर साहब ने कहा— 'तीन बरस से यही किताब पढ़ रहे हो, तुम्हें तो सारे जवाब ज़बानी याद हो गए होंगे! इन लड़कों को अगले साल हाई स्कूल का इम्तहान देना है। तुमसे पारसाल पूछ लूँगा।' टोपी इतना शर्माया कि उसके काले रंग पर लाली दौड़ गई। और जब तमाम बच्चे खिलखिलाकर हँस पड़े तो वह बिलकुल मर गया। जब वह पहली बार नौवें में आया था तो वह भी इन्हीं बच्चों की तरह बिलकुल बच्चा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8057c701-b459-4274-86aa-d9db2b1b0285', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर उसी दिन अब्दुल वहीद ने रिसेस में वह तीर मारा कि टोपी बिलकुल बिलबिला उठा। वहीद क्लास का सबसे तेज़ लड़का था। मॉनीटर भी था। और सबसे बड़ी बात यह है कि वह लाल तेल वाले डॉक्टर शरफुद्दीन का बेटा था। उसने कहा, 'बलभद्र! अबे तो हम लोगन में का घुसता है। एठवालन से दोस्ती कर। हम लोग तो निकल जाएँगे, बाकी तुम्हें तो उन्हीं सबन के साथ रहे को हुई है।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('24603b6f-18ec-478c-a654-effb3937b45a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह बात टोपी के दिल के आर-पार हो गई और उसने कसम खाई कि टाइफाइड हो या टाइफाइड का बाप, उसे पास होना है। परंतु बीच में चुनाव आ गए। डॉक्टर भृगु नारायण नीले तेल वाले खड़े हो गए। अब जिस घर में कोई चुनाव के लिए खड़ा हो गया हो उसमें कोई पढ़-लिख कैसे सकता है!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('14edba57-9acd-4b96-9652-6455f2e0a6ce', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह तो जब डॉक्टर साहब की ज़मानत ज़ब्त हो गई तब घर में ज़रा सन्नाटा हुआ और टोपी ने देखा कि इम्तहान सिर पर खड़ा है। वह पढ़ाई में जुट गया। परंतु ऐसे वातावरण में क्या कोई पढ़ सकता था! इसलिए उसका पास ही हो जाना बहुत था। दादी बोलीं, 'वाह! भगवान नज़र-ए-बद से बचाए। रफ़्तार अच्छी है। तीसरे बरस तीसरे दर्जे में पास तो हो गए।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('da24446e-77f2-4d74-bcee-9c03b7681ae9', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$टोपी शुक्ला 43 कोई उसका दोस्त नहीं रह गया था। आठवें वाले दसवें में थे। सातवें वाले उसके साथ! उनके बीच में वह अच्छा-खासा बूढ़ा दिखाई देता था। वह अपने भरे-पूरे घर ही की तरह अपने स्कूल में भी अकेला हो गया था। मास्टरों ने उसका नोटिस लेना बिलकुल ही छोड़ दिया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dcd27799-0c53-44c3-bd4f-e6ac0470fcaa', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कोई सवाल किया जाता और जवाब देने के लिए वह भी हाथ उठाता तो कोई मास्टर उससे जवाब न पूछता। परंतु जब उसका हाथ उठता ही रहा तो एक दिन अंग्रेजी-साहित्य के मास्टर साहब ने कहा— 'तीन बरस से यही किताब पढ़ रहे हो, तुम्हें तो सारे जवाब ज़बानी याद हो गए होंगे! इन लड़कों को अगले साल हाई स्कूल का इम्तहान देना है। तुमसे पारसाल पूछ लूँगा।' टोपी इतना शर्माया कि उसके काले रंग पर लाली दौड़ गई। और जब तमाम बच्चे खिलखिलाकर हँस पड़े तो वह बिलकुल मर गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('29ceeb8f-4b4d-4763-a240-07785d4d6c55', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब वह पहली बार नौवें में आया था तो वह भी इन्हीं बच्चों की तरह बिलकुल बच्चा था। फिर उसी दिन अब्दुल वहीद ने रिसेस में वह तीर मारा कि टोपी बिलकुल बिलबिला उठा। वहीद क्लास का सबसे तेज़ लड़का था। मॉनीटर भी था। और सबसे बड़ी बात यह है कि वह लाल तेल वाले डॉक्टर शरफुद्दीन का बेटा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('607c10d9-062c-4dd6-80bf-5480bff4ea81', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसने कहा, 'बलभद्र! अबे तो हम लोगन में का घुसता है। एठवालन से दोस्ती कर। हम लोग तो निकल जाएँगे, बाकी तुम्हें तो उन्हीं सबन के साथ रहे को हुई है।' यह बात टोपी के दिल के आर-पार हो गई और उसने कसम खाई कि टाइफाइड हो या टाइफाइड का बाप, उसे पास होना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('83a707a8-0160-468a-a580-d57d26ef1901', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', '3e7c143f-1a41-46e5-92ab-36bfc7b52961', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु बीच में चुनाव आ गए। डॉक्टर भृगु नारायण नीले तेल वाले खड़े हो गए। अब जिस घर में कोई चुनाव के लिए खड़ा हो गया हो उसमें कोई पढ़-लिख कैसे सकता है! वह तो जब डॉक्टर साहब की ज़मानत ज़ब्त हो गई तब घर में ज़रा सन्नाटा हुआ और टोपी ने देखा कि इम्तहान सिर पर खड़ा है। वह पढ़ाई में जुट गया। परंतु ऐसे वातावरण में क्या कोई पढ़ सकता था! इसलिए उसका पास ही हो जाना बहुत था। दादी बोलीं, 'वाह! भगवान नज़र-ए-बद से बचाए। रफ़्तार अच्छी है। तीसरे बरस तीसरे दर्जे में पास तो हो गए।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-649Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL);
